BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO authenticated;
CREATE FUNCTION reception_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label;END IF;RAISE NOTICE 'PASS: %',label;END; $$;
CREATE FUNCTION reception_reject(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS rejected: % [%]',label,SQLERRM;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
INSERT INTO auth.users(id,email) VALUES('c1000000-0000-4000-8000-000000000001','receipt-director@example.test');
INSERT INTO staff_users(auth_id,nom,email,role,must_change_password) VALUES('c1000000-0000-4000-8000-000000000001','Receipt fixture','receipt-director@example.test','directeur',false);
INSERT INTO clients(id,nom,cp,email) VALUES('c2000000-0000-4000-8000-000000000001','Fixture','97400','receipt-client@example.test');
-- Legacy records deliberately retain incomplete, historical measures.
INSERT INTO colis(id,client_id,statut,nb_colis,trackings,trackings_detail,dims_par_colis,notes_reception,fin_l,fin_w,fin_h,fin_p) VALUES
 ('c3000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','attente_feu_vert',2,ARRAY['OLD1','OLD2'],'[{"number":"OLD1"},{"number":"OLD2"}]','[]','Historical note',50,40,30,9),
 ('c3000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000001','autorise',1,ARRAY['KNOWN'],'[{"number":"KNOWN"}]','[{"dimL":10,"dimW":20,"dimH":30,"poids":2.345}]',NULL,45,35,25,4),
 ('c3000000-0000-4000-8000-000000000003','c2000000-0000-4000-8000-000000000001','receptionne',1,ARRAY['STALE'],'[{"number":"STALE"}]','[]',NULL,NULL,NULL,NULL,NULL);
UPDATE colis SET feu_vert='autorise',feu_vert_date=now(),demande_feu_vert_envoyee_at=now() WHERE id='c3000000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
SELECT reception_reject($q$INSERT INTO colis(client_id,statut,nb_colis,trackings_detail) VALUES('c2000000-0000-4000-8000-000000000001','receptionne',1,'[{"number":"A"}]')$q$,'Staff cannot receive an unmeasured carton');
SELECT reception_reject($q$INSERT INTO colis(client_id,statut,nb_colis,trackings_detail,dims_par_colis) VALUES('c2000000-0000-4000-8000-000000000001','mesure',2,'[{"number":"A"},{"number":"B"}]','[{"dimL":10,"dimW":20,"dimH":30,"poids":1}]')$q$,'A second carton cannot reuse the first carton measurements');
SELECT reception_reject($q$INSERT INTO colis(client_id,statut,nb_colis,trackings_detail,dims_par_colis) VALUES('c2000000-0000-4000-8000-000000000001','mesure',1,'[{"number":"A"}]','[{"dimL":10,"dimW":20,"dimH":0,"poids":1}]')$q$,'Zero measurements cannot certify a received carton');
SELECT reception_assert(NOT reception_box_measured('{"dimL":"NaN","dimW":20,"dimH":30,"poids":1}') AND NOT reception_box_measured('{"dimL":10,"dimW":20,"dimH":30,"poids":"Infinity"}'),'Non-finite measurements are rejected');
SELECT reception_reject($q$INSERT INTO colis(client_id,statut,nb_colis,trackings_detail,dims_par_colis,fin_l) VALUES('c2000000-0000-4000-8000-000000000001','mesure',1,'[{"number":"A"}]','[{"dimL":10,"dimW":20,"dimH":30,"poids":1}]',10)$q$,'Receipt cannot prefill optimization measurements');
INSERT INTO colis(id,client_id,statut,nb_colis,trackings_detail,dims_par_colis) VALUES('c3000000-0000-4000-8000-000000000004','c2000000-0000-4000-8000-000000000001','mesure',1,'[{"number":"NEW"}]','[{"dimL":11,"dimW":22,"dimH":33,"poids":1.11}]');
SELECT reception_assert((SELECT dim_l=11 AND dim_w=22 AND dim_h=33 AND poids=1.11 AND fin_l IS NULL AND fin_w IS NULL AND fin_h IS NULL AND fin_p IS NULL AND devis_total IS NULL FROM colis WHERE id='c3000000-0000-4000-8000-000000000004'),'Receipt persists real dimensions without calculating a quote or optimization measures');
UPDATE colis SET notes_reception='Historical note completed',casier='R1' WHERE id='c3000000-0000-4000-8000-000000000001';
SELECT reception_assert((SELECT notes_reception='Historical note completed' AND casier='R1' FROM colis WHERE id='c3000000-0000-4000-8000-000000000001'),'Historical notes and storage position remain editable without remeasurement');
SELECT reception_reject($q$UPDATE colis SET statut='mesure' WHERE id='c3000000-0000-4000-8000-000000000003'$q$,'A status label alone does not prove all cartons were measured');
SELECT reception_reject($q$UPDATE colis SET statut='mesure',nb_colis=3,trackings=ARRAY['OLD1','OLD2','NEW'],trackings_detail='[{"number":"OLD1"},{"number":"OLD2"},{"number":"NEW"}]',dims_par_colis='[null,null,{"dimL":12,"dimW":22,"dimH":32,"poids":1.22}]' WHERE id='c3000000-0000-4000-8000-000000000001'$q$,'Unknown historical cartons cannot be labelled fully measured after an addition');
UPDATE colis SET statut='receptionne',nb_colis=3,trackings=ARRAY['OLD1','OLD2','NEW'],trackings_detail='[{"number":"OLD1"},{"number":"OLD2"},{"number":"NEW"}]',dims_par_colis='[null,null,{"dimL":12,"dimW":22,"dimH":32,"poids":1.22}]' WHERE id='c3000000-0000-4000-8000-000000000001';
SELECT reception_assert((SELECT dims_par_colis->0='null'::jsonb AND dims_par_colis->1='null'::jsonb AND (dims_par_colis->2->>'poids')::numeric=1.22 AND nb_colis=3 AND statut='receptionne' AND dim_l IS NULL AND poids IS NULL FROM colis WHERE id='c3000000-0000-4000-8000-000000000001'),'New measured cartons append without inventing historical measurements or totals');
SELECT reception_assert((SELECT fin_l=50 AND fin_w=40 AND fin_h=30 AND fin_p=9 AND notes_reception='Historical note completed' FROM colis WHERE id='c3000000-0000-4000-8000-000000000001'),'Appending leaves optimization inputs and historical notes unchanged');
SELECT reception_reject($q$UPDATE colis SET statut='mesure',nb_colis=2,trackings=ARRAY['KNOWN','NEW'],trackings_detail='[{"number":"KNOWN"},{"number":"NEW"}]',dims_par_colis='[{"dimL":10,"dimW":20,"dimH":30,"poids":999},{"dimL":15,"dimW":18,"dimH":25,"poids":1.111}]' WHERE id='c3000000-0000-4000-8000-000000000002'$q$,'Appending cannot overwrite known measurements of an older carton');
UPDATE colis SET statut='mesure',nb_colis=2,trackings=ARRAY['KNOWN','NEW'],trackings_detail='[{"number":"KNOWN"},{"number":"NEW"}]',dims_par_colis='[{"dimL":10,"dimW":20,"dimH":30,"poids":2.345},{"dimL":15,"dimW":18,"dimH":25,"poids":1.111}]' WHERE id='c3000000-0000-4000-8000-000000000002';
SELECT reception_assert((SELECT statut='mesure' AND dim_l=15 AND dim_w=20 AND dim_h=30 AND poids=3.46 AND feu_vert='en_attente' AND feu_vert_date IS NULL FROM colis WHERE id='c3000000-0000-4000-8000-000000000002'),'Fully measured addition normalizes receipt aggregates and invalidates old consent');
SELECT reception_assert((SELECT fin_l=45 AND fin_w=35 AND fin_h=25 AND fin_p=4 FROM colis WHERE id='c3000000-0000-4000-8000-000000000002'),'Receipt aggregates never replace final package dimensions');
WITH attempted AS (UPDATE colis SET nb_colis=4 WHERE id='c3000000-0000-4000-8000-000000000001' AND updated_at='2000-01-01' RETURNING id) SELECT reception_assert((SELECT count(*)=0 FROM attempted),'A stale receipt CAS cannot append against a newer carton list');
UPDATE colis SET dims_par_colis='[{"dimL":7,"dimW":null,"dimH":null,"poids":null}]' WHERE id='c3000000-0000-4000-8000-000000000003';
SELECT reception_reject($q$UPDATE colis SET nb_colis=2,trackings_detail='[{"number":"STALE"},{"number":"NEW"}]',dims_par_colis='[null,{"dimL":10,"dimW":20,"dimH":30,"poids":1}]' WHERE id='c3000000-0000-4000-8000-000000000003'$q$,'Appending cannot erase a known coordinate from a partially measured historical carton');
UPDATE colis SET nb_colis=2,trackings_detail='[{"number":"STALE"},{"number":"NEW"}]',dims_par_colis='[{"dimL":7,"dimW":null,"dimH":null,"poids":null},{"dimL":10,"dimW":20,"dimH":30,"poids":1}]' WHERE id='c3000000-0000-4000-8000-000000000003';
SELECT reception_assert((SELECT (dims_par_colis->0->>'dimL')::numeric=7 AND dims_par_colis->0->'dimW'='null'::jsonb AND statut='receptionne' FROM colis WHERE id='c3000000-0000-4000-8000-000000000003'),'Partial historical coordinates are preserved without inventing their missing measurements');
ROLLBACK;
